class Solution {public:
 int minIncrease(int n,vector<vector<int>>& edges,vector<int>& cost){
  vector<vector<int>> g(n);for(auto&e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
  int answer=0;function<pair<long long,int>(int,int)> dfs=[&](int u,int p){
   long long best=0;vector<pair<long long,int>> kids;
   for(int v:g[u])if(v!=p){auto t=dfs(v,u);kids.push_back(t);best=max(best,t.first);}
   int changes=0;for(auto t:kids){changes+=t.second;if(t.first<best)++changes;}
   return make_pair(best+cost[u],changes);
  };return dfs(0,-1).second;
 }
};
